refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yaf_View_Simple::eval


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        $template = "<h1><?php echo htmlspecialchars($title); ?></h1>";

        /* effectue le rendu de la chaîne de template sans accéder au système de fichiers */
        $html = $this->getView()->eval($template, array("title" => "Dernière minute"));

        $this->getResponse()->setBody($html);
        return false; // ignore le rendu automatique
    }
}
?>


   &example.outputs.similar;


<h1>Dernière minute</h1>
